class MenuEntry
{
  unsigned int flags;

public:
  virtual ~MenuEntry() {}
};

class MenuEntryLabel : public MenuEntry
{
protected:
  const char *label;

public:
  virtual ~MenuEntryLabel() {}
};

class MenuEntryTitle : public MenuEntryLabel
{
public:
  virtual ~MenuEntryTitle() {}
};

class ChangeCamMenuEntryFunction : public MenuEntryLabel
{
public:
  virtual ~ChangeCamMenuEntryFunction() {}
};

class DeleteCamMenuEntryFunction : public MenuEntryLabel
{
public:
  virtual ~DeleteCamMenuEntryFunction() {}
};

class Menu
{
  Menu *parent;
  int entries;
  MenuEntry **entry;
  int activeentry;
  bool isopen;
  Menu *closeto;
  void *control;

public:
  virtual ~Menu() {}
  void DelEntry(MenuEntry *ent);
};

class Submenu : public MenuEntryLabel
{
public:
  virtual ~Submenu() {}
};

class camera;

class camMenuObj
{
public:
  camMenuObj(char *name, Menu *menu_parent, camera *cam);
  ~camMenuObj();

  bool deleted;
  bool po_changed;

private:
  camera *p_dbg_cam;
  MenuEntryTitle *cam_title;
  ChangeCamMenuEntryFunction *ent1;
  DeleteCamMenuEntryFunction *ent2;
  Menu *inner_menu;
  Submenu *cam_submenu;
  Menu *parent;
};

camMenuObj::~camMenuObj()
{
  inner_menu->DelEntry(cam_title);
  inner_menu->DelEntry(ent1);
  inner_menu->DelEntry(ent2);
  delete cam_title;
  delete ent1;
  delete ent2;
  parent->DelEntry(cam_submenu);
  delete inner_menu;
  delete cam_submenu;
}
